import React, { useEffect, useState } from "react";
import { Plus, Trash2, MessageSquare } from "lucide-react";
import api from "../services/api";

export default function Grievances() {
    const [data, setData] = useState([]);
    const [open, setOpen] = useState(false);
    const [msg, setMsg] = useState("");
    const [error, setError] = useState("");

    const [form, setForm] = useState({
        memberName: "",
        category: "Payment",
        subject: "",
        priority: "Medium",
        description: ""
    });

    // Load grievances
    const load = async () => {
        try {
            const response = await api.get("/grievances");
            setData(response.data);
        } catch (err) {
            console.error("Grievances loading error:", err);
            setData([]);
        }
    };

    // IMPORTANT:
    // Do not use useEffect(load, [])
    // because load() returns a Promise.
    useEffect(() => {
        load();
    }, []);

    // Handle input changes
    const handleChange = (e) => {
        const { name, value } = e.target;

        setForm((prev) => ({
            ...prev,
            [name]: value
        }));
    };

    // Submit grievance
    const submit = async (e) => {
        e.preventDefault();

        setMsg("");
        setError("");

        try {
            await api.post("/grievances", form);

            setMsg("Grievance submitted successfully.");

            setForm({
                memberName: "",
                category: "Payment",
                subject: "",
                priority: "Medium",
                description: ""
            });

            setOpen(false);

            await load();

        } catch (err) {
            console.error("Grievance submission error:", err);

            setError(
                err.response?.data?.message ||
                "Unable to submit grievance."
            );
        }
    };

    // Delete grievance
    const deleteGrievance = async (id) => {
        try {
            await api.delete(`/grievances/${id}`);

            setMsg("Grievance deleted successfully.");

            await load();

        } catch (err) {
            console.error("Delete grievance error:", err);

            setError(
                err.response?.data?.message ||
                "Unable to delete grievance."
            );
        }
    };

    return (
        <>
            {/* PAGE HEADER */}
            <div className="page-head">
                <div>
          <span className="eyebrow">
            FARMER SUPPORT
          </span>

                    <h2>
                        Grievances & Feedback
                    </h2>

                    <p>
                        Submit and manage farmer complaints, issues and feedback.
                    </p>
                </div>

                <button
                    className="primary"
                    onClick={() => {
                        setOpen(true);
                        setMsg("");
                        setError("");
                    }}
                >
                    <Plus size={17} />
                    Add grievance
                </button>
            </div>

            {/* SUCCESS MESSAGE */}
            {msg && (
                <div className="alert success-alert">
                    {msg}
                </div>
            )}

            {/* ERROR MESSAGE */}
            {error && (
                <div className="alert">
                    {error}
                </div>
            )}

            {/* GRIEVANCE LIST */}
            <div className="panel">

                <div className="panel-head">
                    <div>
                        <h3>
                            Grievance Records
                        </h3>

                        <p>
                            View submitted farmer complaints and feedback.
                        </p>
                    </div>
                </div>

                {data.length > 0 ? (

                    <div className="table-wrap">

                        <table>

                            <thead>
                            <tr>
                                <th>Member</th>
                                <th>Category</th>
                                <th>Subject</th>
                                <th>Priority</th>
                                <th>Status</th>
                                <th>Date</th>
                                <th>Action</th>
                            </tr>
                            </thead>

                            <tbody>

                            {data.map((g) => (

                                <tr key={g.id}>

                                    <td>
                                        <b>
                                            {g.memberName || "-"}
                                        </b>
                                    </td>

                                    <td>
                                        {g.category || "-"}
                                    </td>

                                    <td>
                                        {g.subject || "-"}
                                    </td>

                                    <td>
                      <span className="badge warning">
                        {g.priority || "Medium"}
                      </span>
                                    </td>

                                    <td>
                      <span className="badge pending">
                        {g.status || "OPEN"}
                      </span>
                                    </td>

                                    <td>
                                        {g.createdAt
                                            ? String(g.createdAt)
                                                .replace("T", " ")
                                                .substring(0, 16)
                                            : "-"}
                                    </td>

                                    <td>
                                        <button
                                            className="small-btn danger-btn"
                                            onClick={() =>
                                                deleteGrievance(g.id)
                                            }
                                        >
                                            <Trash2 size={15} />
                                        </button>
                                    </td>

                                </tr>

                            ))}

                            </tbody>

                        </table>

                    </div>

                ) : (

                    <div className="empty">

                        <MessageSquare size={30} />

                        <p>
                            No grievances found.
                        </p>

                    </div>

                )}

            </div>

            {/* ADD GRIEVANCE MODAL */}
            {open && (

                <div className="modal-bg">

                    <form
                        className="modal grievance-modal"
                        onSubmit={submit}
                    >

                        {/* MODAL HEADER */}
                        <div className="modal-head">

                            <div>
                                <h3>
                                    Submit Grievance
                                </h3>

                                <p>
                                    Record a farmer complaint or feedback.
                                </p>
                            </div>

                            <button
                                type="button"
                                onClick={() => setOpen(false)}
                            >
                                ×
                            </button>

                        </div>

                        {/* FORM */}
                        <div className="form-grid">

                            {/* MEMBER NAME */}
                            <label>
                                Member Name

                                <input
                                    type="text"
                                    name="memberName"
                                    required
                                    placeholder="Enter member name"
                                    value={form.memberName}
                                    onChange={handleChange}
                                />

                            </label>

                            {/* CATEGORY */}
                            <label>
                                Category

                                <select
                                    name="category"
                                    value={form.category}
                                    onChange={handleChange}
                                >
                                    <option value="Payment">
                                        Payment
                                    </option>

                                    <option value="Procurement">
                                        Procurement
                                    </option>

                                    <option value="Warehouse">
                                        Warehouse
                                    </option>

                                    <option value="Sales">
                                        Sales
                                    </option>

                                    <option value="Share Capital">
                                        Share Capital
                                    </option>

                                    <option value="Dividend">
                                        Dividend
                                    </option>

                                    <option value="Other">
                                        Other
                                    </option>
                                </select>

                            </label>

                            {/* SUBJECT */}
                            <label>
                                Subject

                                <input
                                    type="text"
                                    name="subject"
                                    required
                                    placeholder="Enter subject"
                                    value={form.subject}
                                    onChange={handleChange}
                                />

                            </label>

                            {/* PRIORITY */}
                            <label>
                                Priority

                                <select
                                    name="priority"
                                    value={form.priority}
                                    onChange={handleChange}
                                >

                                    <option value="Low">
                                        Low
                                    </option>

                                    <option value="Medium">
                                        Medium
                                    </option>

                                    <option value="High">
                                        High
                                    </option>

                                    <option value="Critical">
                                        Critical
                                    </option>

                                </select>

                            </label>

                            {/* DESCRIPTION - FULL WIDTH */}
                            <label className="grievance-description">

                                Description

                                <textarea
                                    name="description"
                                    required
                                    placeholder="Describe the problem..."
                                    value={form.description}
                                    onChange={handleChange}
                                />

                            </label>

                        </div>

                        {/* SUBMIT BUTTON */}
                        <button
                            type="submit"
                            className="primary full"
                        >
                            Submit Grievance
                        </button>

                    </form>

                </div>

            )}

        </>
    );
}
